15	static os_log_t TweakLog(void) {
16	    static os_log_t log;
17	    static dispatch_once_t once;
18	    dispatch_once(&once, ^{
19	        log = os_log_create(APELIN_PACKAGE_ID, "tweak");
20	    });
21	    return log;
22	}
23	
24	static void (*OriginalDidFinishLaunching)(id self, SEL _cmd, id application);
25	
26	// -[SpringBoard applicationDidFinishLaunching:] runs once per SpringBoard
27	// launch, after the constructor below has installed the hook.
28	static void HookedDidFinishLaunching(id self, SEL _cmd, id application) {
29	    if (OriginalDidFinishLaunching != NULL) {
30	        OriginalDidFinishLaunching(self, _cmd, application);
31	    }
32	    os_log(TweakLog(), "ApelinHooked %{public}s -[SpringBoard applicationDidFinishLaunching:]", APELIN_BUILD_ID);
33	}
34	
35	__attribute__((constructor)) static void TweakInitialize(void) {
36	    // Apelin's confirm_loaded looks for this exact marker and build id under
37	    // the package id's subsystem. Keep the line, and keep it public.
38	    os_log(TweakLog(), "ApelinLoaded %{public}s in %{public}s", APELIN_BUILD_ID, getprogname());
39	
40	    Class springBoard = objc_getClass("SpringBoard");
41	    if (springBoard == Nil) {
42	        return;  // Loaded into some other process the filter names.
43	    }
44	    MSHookMessageEx(springBoard,
45	                    @selector(applicationDidFinishLaunching:),
46	                    (IMP)HookedDidFinishLaunching,
47	                    (IMP *)&OriginalDidFinishLaunching);
48	}
